/* Browse published tuition dates and recorded sessions without creating future ledger entries. */
let attendanceDay=AcademyDates.today(),attendanceMode='day',attendanceTeacher='',attendanceSearch='';const attendanceSaving=new Set();
const tehranDay=value=>new Date(value).toLocaleDateString('en-CA',{timeZone:'Asia/Tehran'});
function shiftISO(day,n){const d=new Date(day+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+n);return d.toISOString().slice(0,10)}
function dailyClassRows(day=attendanceDay){
 const rows=db.sessions.filter(c=>tehranDay(c.starts_at)===day).map(c=>{const student=db.students.find(s=>s.id===c.student_id),t=monthRows.find(t=>t.student_id===c.student_id&&t.dates.includes(day));return {day,student,session:c,time:new Date(c.starts_at).toLocaleTimeString('en-GB',{timeZone:'Asia/Tehran',hour:'2-digit',minute:'2-digit'}),paid:t?!!t.paid[t.dates.indexOf(day)]:!!(student&&eligible(student))}});
 for(const t of monthRows){if(!t.published)continue;const i=t.dates.indexOf(day),s=db.students.find(s=>s.id===t.student_id);if(i<0||!s||s.archived_at||rows.some(r=>r.student?.id===s.id))continue;rows.push({day,student:s,time:s.class_time.slice(0,5),paid:!!t.paid[i],session:null})}
 return rows.filter(r=>r.student&&(!r.student.archived_at||r.session)).sort((a,b)=>a.time.localeCompare(b.time));
}
function attendanceRange(){if(attendanceMode==='month'){const m=monthCalendar.find(m=>m.starts_on<=attendanceDay&&m.ends_on>=attendanceDay);if(m)return [m.starts_on,m.ends_on];const key=AcademyDates.show(attendanceDay).replace(/[۰-۹]/g,c=>'۰۱۲۳۴۵۶۷۸۹'.indexOf(c)).slice(0,7),first=AcademyDates.iso(key+'/01');let last=first;while(AcademyDates.show(shiftISO(last,1)).slice(0,7)===AcademyDates.show(first).slice(0,7))last=shiftISO(last,1);return [first,last]}
 if(attendanceMode==='week'){const dow=new Date(attendanceDay+'T12:00:00Z').getUTCDay(),first=shiftISO(attendanceDay,-((dow+1)%7));return [first,shiftISO(first,6)]}return [attendanceDay,attendanceDay]}
function attendanceRows(){const [first,last]=attendanceRange(),rows=[];for(let day=first;day<=last;day=shiftISO(day,1))rows.push(...dailyClassRows(day));const normalize=s=>String(s||'').replace(/ي/g,'ی').replace(/ك/g,'ک').replace(/[\s\u200c]/g,'').toLowerCase(),q=normalize(attendanceSearch);return rows.filter(r=>(!attendanceTeacher||r.student.teacher_id===attendanceTeacher)&&(!q||normalize(full(r.student)+' '+r.student.subject).includes(q)))}
function attendanceTableRow(r){
 const locked=!r.paid||r.day>AcademyDates.today()||r.session&&r.session.status!=='scheduled';
 const action=status=>`markDailyAttendance('${r.student.id}','${status}',this,'${r.day}','${r.session?.id||''}')`;
 const buttons=!r.session||r.session.status==='scheduled'?`<button class="primary" onclick="${action('completed')}" ${locked?'disabled':''}>✓ حاضر</button> <button onclick="${action('absent')}" ${locked?'disabled':''}>غایب</button>${r.day>AcademyDates.today()?'<small class="sub">روز کلاس فعال می‌شود</small>':''}`:'ثبت شد';
 return `<tr><td>${AcademyDates.show(r.day)}<small class="sub">${new Date(r.day+'T12:00:00Z').toLocaleDateString('fa-IR',{weekday:'long'})}</small></td><td dir="ltr"><b>${r.time}</b></td><td>${esc(full(r.student))}</td><td>${window.teacherInline?window.teacherInline(teacher(r.student.teacher_id)):esc(teacher(r.student.teacher_id))}<small class="sub">${esc(r.student.subject)}</small></td><td><span class="badge ${r.paid?'':'red'}">${r.paid?'پرداخت‌شده':'پرداخت نشده'}</span></td><td>${r.session?esc(statusLabel(r.session.status)):'برنامه‌ریزی شده'}</td><td>${buttons}</td></tr>`;
}
function attendanceResults(){const rows=attendanceRows(),[first,last]=attendanceRange();return `<p class="sub" aria-live="polite">${AcademyDates.show(first)}${first!==last?' تا '+AcademyDates.show(last):''} · ${money(rows.length)} کلاس</p>${rows.length?table(['تاریخ','ساعت','هنرجو','استاد و رشته','شهریه','وضعیت جلسه','ثبت حضور'],rows.map(attendanceTableRow)):'<div class="empty">در این بازه و با این فیلترها کلاسی ثبت نشده است. ماه دیگری را انتخاب کنید؛ نمایش آینده به ثبت و انتشار شهریهٔ آن ماه نیاز دارد.</div>'}`}
function updateAttendanceResults(){const target=document.getElementById('attendance-results');if(target)target.innerHTML=attendanceResults()}
function setAttendanceDate(value){try{attendanceDay=AcademyDates.iso(value);render()}catch(e){toast(e.message)}}
function shiftAttendanceDay(offset){if(attendanceMode==='month'){const [first,last]=attendanceRange();attendanceDay=offset>0?shiftISO(last,1):shiftISO(first,-1)}else attendanceDay=shiftISO(attendanceDay,offset*(attendanceMode==='week'?7:1));render()}
function attendancePanel(){if(!admin)return '';return `<section class="card daily-attendance"><style>.attendance-browser{display:flex;flex-wrap:wrap;gap:16px;align-items:end;margin:20px 0}.attendance-browser label{display:flex;flex-direction:column;gap:8px;flex:1;min-width:180px;font-size:14px}.attendance-browser input,.attendance-browser select{width:100%;min-height:44px;padding:10px;border:1px solid #dacbb6;border-radius:12px;background:#fffdf8;color:#503b2d;font:inherit}.attendance-browser .persian-date-picker{display:flex;flex-wrap:wrap;gap:5px}.attendance-browser .persian-date-picker select{min-width:0;width:auto;flex:1}.attendance-browser .persian-date-picker button{padding:8px}.attendance-browser-actions{display:flex;gap:8px;flex-wrap:wrap}.attendance-browser-actions button{min-height:44px}.daily-attendance .responsive-table button{margin:3px;min-height:40px}@media(max-width:600px){.attendance-browser label{min-width:100%}.attendance-browser-actions{width:100%}.attendance-browser-actions button{flex:1}}</style><div class="cardhead"><div><h3>برنامهٔ کلاس‌ها و حضور هنرجویان</h3><p class="sub">تاریخ دلخواه را انتخاب کنید؛ برنامهٔ گذشته و آینده را در همان جدول ببینید.</p></div></div><div class="attendance-browser"><label>تاریخ شمسی<input value="${AcademyDates.show(attendanceDay)}" data-persian-date onchange="setAttendanceDate(this.value)" placeholder="۱۴۰۵/۰۹/۰۱" aria-label="تاریخ برنامه کلاس‌ها"></label><label>بازهٔ نمایش<select onchange="attendanceMode=this.value;render()" aria-label="بازه نمایش کلاس‌ها">${[['day','روزانه'],['week','هفتگی'],['month','ماهانه']].map(([v,l])=>`<option value="${v}" ${attendanceMode===v?'selected':''}>${l}</option>`).join('')}</select></label><label>استاد<select onchange="attendanceTeacher=this.value;updateAttendanceResults()" aria-label="فیلتر استاد"><option value="">همهٔ اساتید</option>${db.teachers.map(t=>`<option value="${esc(t.id)}" ${attendanceTeacher===t.id?'selected':''}>استاد ${esc(t.name)}</option>`).join('')}</select></label><label>جست‌وجوی هنرجو یا رشته<input value="${esc(attendanceSearch)}" type="search" oninput="attendanceSearch=this.value;updateAttendanceResults()" placeholder="نام هنرجو یا رشته…"></label></div><div class="attendance-browser-actions"><button onclick="shiftAttendanceDay(-1)">→ بازهٔ قبل</button><button onclick="attendanceDay=AcademyDates.today();render()">امروز</button><button onclick="shiftAttendanceDay(1)">بازهٔ بعد ←</button><button onclick="attendanceDay=AcademyDates.start;attendanceMode='month';render()">برنامهٔ آذر ۱۴۰۵</button></div><div id="attendance-results">${attendanceResults()}</div><p class="sub">نمایش کلاس‌ها به پرداخت وابسته نیست. ثبت حضور فقط برای جلسهٔ پرداخت‌شده در روز جاری یا گذشته امکان دارد.</p></section>`}
async function markDailyAttendance(studentId,status,button,day=attendanceDay,sessionId=''){const key=studentId+':'+day+':'+sessionId;if(!admin||attendanceSaving.has(key)||!['completed','absent'].includes(status))return;const r=dailyClassRows(day).find(r=>r.student.id===studentId&&(!sessionId||r.session?.id===sessionId));if(!r||!r.paid||day>AcademyDates.today()||r.session&&r.session.status!=='scheduled')return;attendanceSaving.add(key);button.disabled=true;try{if(r.session){const result=await api('/rest/v1/sessions?id=eq.'+encodeURIComponent(r.session.id)+'&status=eq.scheduled','PATCH',{status});if(!result?.length)throw Error('وضعیت جلسه تغییر کرده؛ صفحه را به‌روزرسانی کنید')}else await api('/rest/v1/sessions','POST',{student_id:studentId,starts_at:day+'T'+r.time+':00+03:30',status});await reload();toast(status==='completed'?'حضور هنرجو ثبت شد':'غیبت هنرجو ثبت شد')}catch(e){toast(e.message);await reload().catch(()=>{})}finally{attendanceSaving.delete(key);button.disabled=false}}
function teacherAllocationPanel(){if(!admin)return '';const groups=new Map();for(const p of dashboardPayments()){const s=db.students.find(s=>s.id===p.student_id),key=s?.teacher_id||'unknown';if(!groups.has(key))groups.set(key,{gross:0,share:0});const g=groups.get(key);g.gross+=Number(p.amount)||0;}return `<div class="card"><h3>تفکیک سهم اساتید از دریافتی</h3><p class="sub">۶۰٪ دریافتی متعلق به استاد مربوطه و ۴۰٪ سهم آموزشگاه است. این جدول تخصیص دریافتی است؛ تسویهٔ حقوق در بخش اساتید ثبت می‌شود.</p>${table(['استاد','کل دریافتی کلاس‌ها','سهم استاد · ۶۰٪','سهم آموزشگاه · ۴۰٪'],[...groups].map(([id,g])=>`<tr><td>${id==='unknown'?'نیازمند اتصال به کلاس':window.teacherInline?window.teacherInline(teacher(id)):esc(teacher(id))}</td><td>${money(g.gross)}</td><td>${money(Math.round(g.gross*.6))}</td><td>${money(g.gross-Math.round(g.gross*.6))}</td></tr>`))}</div>`;}
const operationsDashboard=views.dashboard;views.dashboard=function(){return operationsDashboard()+attendancePanel()+teacherAllocationPanel();};
const operationsSchedule=views.schedule;views.schedule=function(){return admin?title('تقویم کلاس‌ها','مشاهدهٔ برنامه در تاریخ و بازهٔ دلخواه',btn('ایجاد ۴ جلسه ترم','generateTerm()'))+attendancePanel():operationsSchedule();};
